{
  "name": "semaphore-cli",
  "version": "0.1.0",
  "description": "CLI for the USB-HID traffic-light semaphore device (VID 0x1209, PID 0x0001).",
  "bin": {
    "semaphore": "cli.js"
  },
  "files": [
    "cli.js",
    "scripts"
  ],
  "scripts": {
    "postinstall": "node scripts/postinstall.js",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "keywords": [
    "hid",
    "usb",
    "led",
    "traffic-light",
    "semaphore",
    "claude-code",
    "hooks"
  ],
  "author": "Artem Makarov",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/artemy/semaphore.git"
  },
  "homepage": "https://github.com/artemy/semaphore#readme",
  "bugs": {
    "url": "https://github.com/artemy/semaphore/issues"
  },
  "type": "commonjs",
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "node-hid": "3.3.0"
  },
  "allowScripts": {
    "node-hid@3.3.0": true
  }
}
